"""Freeze a complete follow-up source/evidence selection after all writers stop.

This uses the previous packager's read-only evidence selection API without
changing the old script. It omits only the explicitly listed derived JFR event
expansions, retaining their sizes/hashes/reason in a new audit. All original
on-disk evidence remains untouched. No archive, Git index, build or Java process
is created. Omission hashing is deliberate and must happen after timings.
"""

from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import runpy
import tempfile
import time

from comparison_runtime_io import FOLLOWUP, file_hash, json_bytes, path_under, portable, require, signature


def publish_file(path: Path, data: bytes) -> None:
    descriptor, temporary_name = tempfile.mkstemp(prefix=".selection-", dir=path.parent)
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.link(temporary, path)
    finally:
        temporary.unlink()


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parents[2])
    parser.add_argument("--policy", default=FOLLOWUP + "/selection-policy.json")
    parser.add_argument("--output", default=FOLLOWUP + "/delivery-selection.json")
    parser.add_argument("--audit", default=FOLLOWUP + "/delivery-selection-audit.json")
    parser.add_argument("--report", action="append", default=[])
    parser.add_argument("--source", action="append", default=[], help="Additional exact source/task file")
    parser.add_argument("--small-text-bytes", type=int, default=2 * 1024 * 1024)
    args = parser.parse_args()
    repo = args.repo.resolve(strict=True)
    output_relative, audit_relative = portable(args.output), portable(args.audit)
    output, audit_path = repo / output_relative, repo / audit_relative
    require(output != audit_path and not os.path.lexists(output) and not os.path.lexists(audit_path),
            "Selection and audit outputs must be distinct new files")
    require(output.parent.resolve(strict=True).is_relative_to(repo)
            and audit_path.parent.resolve(strict=True).is_relative_to(repo), "Output parent escapes repository")
    policy_relative = portable(args.policy)
    policy = json.loads(path_under(repo, policy_relative).read_bytes())
    require(policy["format"] == 1 and policy["archivePrefix"] == "rdf4j", "Unexpected selection policy")
    previous = json.loads(path_under(repo, policy["baseSelection"]).read_bytes())
    source = set(previous.get("source_include", [])) | set(policy["topLevelSourceJson"]) | set(args.source)
    source.add(policy_relative)
    for path in (repo / FOLLOWUP).iterdir():
        if path.is_file() and not path.is_symlink() and path.suffix.lower() in {".py", ".md", ".java", ".jfc"}:
            source.add(path.relative_to(repo).as_posix())
    reports = set(previous.get("reports", [])) | set(args.report)
    source.update(reports)
    for relative in source:
        require(path_under(repo, portable(relative)).is_file(), f"Selected task source is not a file: {relative}")
    packager = repo / "result-coordinate-evidence/package-coordinate-deliverables.py"
    # run_path executes only definitions/imports: the old script's main is guarded.
    api = runpy.run_path(str(packager))
    candidates, standard_omissions = api["collect_evidence"](
        repo, set(policy["evidenceRoots"]), set(source), args.small_text_bytes)
    omitted = []
    for relative in policy["derivedExpansionsToOmit"]:
        relative = portable(relative)
        path = repo / relative
        if not path.exists():
            continue
        path = path_under(repo, relative)
        before = signature(path)
        digest = file_hash(path)
        require(signature(path) == before, f"Derived expansion changed while recording omission: {relative}")
        require(relative in candidates, f"Derived expansion is not otherwise selected evidence: {relative}")
        candidates.pop(relative)
        omitted.append({"path": relative, "bytes": before[3], "sha256": digest, "reason": policy["omissionReason"]})
    require(not (set(policy["derivedExpansionsToOmit"]) & source), "Derived expansion cannot be selected as source")
    source.update((output_relative, audit_relative))
    evidence = set(candidates) | source
    selection = {"source_include": sorted(source), "evidence_roots": [],
                 "evidence_include": sorted(evidence), "reports": sorted(reports)}
    selection_bytes = json_bytes(selection)
    import hashlib
    audit = {"format": 1, "createdEpochNs": time.time_ns(), "policy": policy_relative,
             "previousSelection": policy["baseSelection"], "selection": output_relative,
             "selectionSha256": hashlib.sha256(selection_bytes).hexdigest(),
             "explicitEvidenceFiles": len(evidence), "selectedTaskSourceFiles": len(source),
             "derivedExpansionsOmitted": omitted, "standardPackagerOmissions": standard_omissions,
             "sanitizedJfrDelivery": "Self-contained rdf4j-materializer-comparison-runtime.tar.gz; original raw recordings remain private",
             "allOriginalFilesPreserved": True, "noGitIndexOrArchiveOrJavaOperation": True,
             "condition": "This is a closed inventory. Stop all evidence writers before selection; regenerate to a new filename if membership changes."}
    publish_file(audit_path, json_bytes(audit))
    publish_file(output, selection_bytes)
    print(f"Created closed follow-up selection: {output}; {len(evidence)} explicit evidence files")
    print(f"Recorded {len(omitted)} derived expansion omissions without removing files: {audit_path}")


if __name__ == "__main__":
    main()
